package com.example

/**
 * 11 ශ්‍රේණිය ඉතිහාසය - කාණ්ඩ 5 සිට 10 දක්වා (120 unique cards).
 * 100% curriculum-aligned with official Sri Lankan O/L Grade 11 History Syllabus.
 */
object FlashcardBankHistoryGrade11SetsPart1 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      5 -> set5SoulburyAndIndependence[(c - 1) % 20]
      6 -> set6Constitutions1972And1978[(c - 1) % 20]
      7 -> set7IndustrialRevolution[(c - 1) % 20]
      8 -> set8WorldWarOne[(c - 1) % 20]
      9 -> set9WorldWarTwoAndUN[(c - 1) % 20]
      10 -> set10WorldCivilizations[(c - 1) % 20]
      else -> null
    }
  }

